#!/usr/bin/env node
/**
 * bundle-api-keys.js — 빌드 시 외부 API 키를 앱에 임베드
 *
 * 동작:
 *   1. electron-app/api-keys.json 읽기 (없으면 빈 키로 진행)
 *   2. src/main/services/bundled-api-keys.js 생성 (CommonJS module)
 *
 * 키들은 data.go.kr 공공데이터 공통 인증키이며, 평문 임베드해도
 * 정책상 큰 위험이 없다. (사용자가 직접 발급받은 키를 입력하는 절차를
 * 생략하기 위함)
 *
 * 임베드된 키는 첫 실행 시 localStorage 가 비어 있으면 자동 채워진다.
 */
'use strict';

const fs   = require('fs');
const path = require('path');

const ROOT     = path.join(__dirname, '..');
const SRC_FILE = path.join(ROOT, 'api-keys.json');
const OUT_FILE = path.join(ROOT, 'src', 'main', 'services', 'bundled-api-keys.js');

const KEYS = ['kma_api_key','airkorea_api_key','drug_api_key','hira_api_key','emergency_api_key','kakao_rest_api_key','kakao_js_api_key'];

function loadKeys() {
  if (!fs.existsSync(SRC_FILE)) {
    console.warn('[bundle-api-keys] api-keys.json 파일이 없습니다 — 빈 키로 진행합니다.');
    const empty = {};
    KEYS.forEach(k => { empty[k] = ''; });
    return empty;
  }
  const raw = JSON.parse(fs.readFileSync(SRC_FILE, 'utf8'));
  const out = {};
  KEYS.forEach(k => { out[k] = (typeof raw[k] === 'string') ? raw[k].trim() : ''; });
  return out;
}

function generate(keys) {
  return `'use strict';
/* AUTO-GENERATED by scripts/bundle-api-keys.js — do not edit */
module.exports = ${JSON.stringify(keys, null, 2)};
`;
}

function run() {
  console.log('[bundle-api-keys] 외부 API 키 번들 생성 시작...');
  const keys = loadKeys();
  const outDir = path.dirname(OUT_FILE);
  if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(OUT_FILE, generate(keys), 'utf8');
  const filled = Object.entries(keys).filter(([k,v])=>v).map(([k])=>k);
  console.log('[bundle-api-keys] 생성 완료:', path.relative(ROOT, OUT_FILE));
  console.log('[bundle-api-keys] 임베드된 키:', filled.length ? filled.join(', ') : '(없음)');
}

run();
